class Solution {
    public List<String> stringMatching(String[] words){
        List<String> answer=new ArrayList<>();
        for(int i=0;i<words.length;i++)for(int j=0;j<words.length;j++)if(i!=j&&words[j].contains(words[i])){
            answer.add(words[i]);
            break;
        }
        return answer;
    }
}

code.kotlin:
class Solution {
    fun stringMatching(words:Array<String>):List<String>{
        val answer=mutableListOf<String>();
        for(i in words.indices)for(j in words.indices)if(i!=j&&words[j].contains(words[i])){
            answer.add(words[i]);
            break
        };
        return answer
    }
}

code.cpp:
class Solution {
    public: vector<string> stringMatching(vector<string>& words){
        vector<string> answer;
        for(int i=0;i<(int)words.size();++i)for(int j=0;j<(int)words.size();++j)if(i!=j&&words[j].find(words[i])!=string::npos){
            answer.push_back(words[i]);
            break;
        }
        return answer;
    }
};
